 code:"#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char str[100] = \"Programming\";\n    int count = 0;\n\n    for (int i = 0; str[i] != '\\0'; i++) {\n        char c = str[i];\n        if (c=='a'||c=='e'||c=='i'||c=='o'||c=='u'||\n            c=='A'||c=='E'||c=='I'||c=='O'||c=='U')\n            count++;\n    }\n    printf(\"Number of vowels = %d\", count);\n    return 0;\n}",
